class Solution {
    public int minPathWeight(int n, int[][] edges, String labels, int k) {
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) adj[e[0]].add(new int[]{e[1], e[2]});
        int[][] dist = new int[n][k + 1];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][1] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{0, 0, 1});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], u = top[1], r = top[2];
            if (d > dist[u][r]) continue;
            if (u == n - 1) return d;
            for (int[] ed : adj[u]) {
                int v = ed[0], w = ed[1];
                int nr = (labels.charAt(v) == labels.charAt(u)) ? r + 1 : 1;
                if (nr <= k && d + w < dist[v][nr]) {
                    dist[v][nr] = d + w;
                    pq.offer(new int[]{d + w, v, nr});
                }
            }
        }
        return -1;
    }
}

