var minPathWeight = function(n, edges, labels, k) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) adj[u].push([v, w]);
    const INF = Infinity;
    const dist = Array.from({length: n}, () => new Array(k + 1).fill(INF));
    dist[0][1] = 0;
    const pq = [[0, 0, 1]];
    while (pq.length) {
        let bi = 0;
        for (let i = 1; i < pq.length; i++) if (pq[i][0] < pq[bi][0]) bi = i;
        const [d, u, r] = pq.splice(bi, 1)[0];
        if (d > dist[u][r]) continue;
        if (u === n - 1) return d;
        for (const [v, w] of adj[u]) {
            const nr = labels[v] === labels[u] ? r + 1 : 1;
            if (nr <= k && d + w < dist[v][nr]) {
                dist[v][nr] = d + w;
                pq.push([d + w, v, nr]);
            }
        }
    }
    return -1;
};

