class Solution:
    def minPathWeight(self, n: int, edges: List[List[int]], labels: str, k: int) -> int:
        INF = float('inf')
        dist = [[INF] * (k + 1) for _ in range(n)]
        dist[0][1] = 0
        for _ in range(n * k + 1):
            changed = False
            nd = [row[:] for row in dist]
            for u, v, w in edges:
                for r in range(1, k + 1):
                    if dist[u][r] == INF: continue
                    nr = r + 1 if labels[v] == labels[u] else 1
                    if nr <= k and dist[u][r] + w < nd[v][nr]:
                        nd[v][nr] = dist[u][r] + w
                        changed = True
            dist = nd
            if not changed: break
        ans = min(dist[n - 1])
        return ans if ans < INF else -1

