class Solution {
public:
    int minPathWeight(int n, vector<vector<int>>& edges, string labels, int k) {
        const long long INF = LLONG_MAX / 2;
        vector<vector<long long>> dist(n, vector<long long>(k + 1, INF));
        dist[0][1] = 0;
        for (int it = 0; it <= n * k; ++it) {
            bool changed = false;
            auto nd = dist;
            for (auto& e : edges)
                for (int r = 1; r <= k; ++r) {
                    if (dist[e[0]][r] >= INF) continue;
                    int nr = (labels[e[1]] == labels[e[0]]) ? r + 1 : 1;
                    if (nr <= k && dist[e[0]][r] + e[2] < nd[e[1]][nr]) {
                        nd[e[1]][nr] = dist[e[0]][r] + e[2];
                        changed = true;
                    }
                }
            dist = nd;
            if (!changed) break;
        }
        long long ans = *min_element(dist[n - 1].begin(), dist[n - 1].end());
        return ans >= INF ? -1 : (int)ans;
    }
};

