class Solution {
    public int minPathWeight(int n, int[][] edges, String labels, int k) {
        long INF = Long.MAX_VALUE / 2;
        long[][] dist = new long[n][k + 1];
        for (long[] row : dist) Arrays.fill(row, INF);
        dist[0][1] = 0;
        for (int it = 0; it <= n * k; it++) {
            boolean changed = false;
            long[][] nd = new long[n][];
            for (int i = 0; i < n; i++) nd[i] = dist[i].clone();
            for (int[] e : edges)
                for (int r = 1; r <= k; r++) {
                    if (dist[e[0]][r] >= INF) continue;
                    int nr = (labels.charAt(e[1]) == labels.charAt(e[0])) ? r + 1 : 1;
                    if (nr <= k && dist[e[0]][r] + e[2] < nd[e[1]][nr]) {
                        nd[e[1]][nr] = dist[e[0]][r] + e[2];
                        changed = true;
                    }
                }
            dist = nd;
            if (!changed) break;
        }
        long ans = INF;
        for (int r = 1; r <= k; r++) ans = Math.min(ans, dist[n - 1][r]);
        return ans >= INF ? -1 : (int) ans;
    }
}

