    for (let it = 0; it <= n * k; it++) {
        let changed = false;
        const nd = dist.map(row => row.slice());
        for (const [u, v, w] of edges)
            for (let r = 1; r <= k; r++) {
                if (dist[u][r] === INF) continue;
                const nr = labels[v] === labels[u] ? r + 1 : 1;
                if (nr <= k && dist[u][r] + w < nd[v][nr]) {
                    nd[v][nr] = dist[u][r] + w;
                    changed = true;
                }
            }
        for (let i = 0; i < n; i++) dist[i] = nd[i];
        if (!changed) break;
    }
    const ans = Math.min(...dist[n - 1]);
    return ans === INF ? -1 : ans;
};
